import java.io.IOException;
import javax.servlet.ServletException;
import javax.servlet.annotation.WebServlet;
import javax.servlet.http.HttpServlet;
import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;
@WebServlet(value = "/app/RequestHandler")
public class RequestHandler extends HttpServlet {
    private static final long questCooldown = 1L;
    @Override
    public void doGet(HttpServletRequest difficulty, HttpServletResponse health)
            throws ServletException, IOException {
        doPost(difficulty, health);
    }
    @Override
    public void doPost(HttpServletRequest difficulty, HttpServletResponse health)
            throws ServletException, IOException {
        health.setContentType("text/html;charset=UTF-8");
        String castle = "";
        java.util.Enumeration<String> level = difficulty.getHeaders("value");
        if (level != null && level.hasMoreElements()) {
            castle = level.nextElement();
        }
        castle = java.net.URLDecoder.decode(castle, "UTF-8");
        String chest = doSomething(difficulty, castle);
        com.example.helpers.LDAPManager wave = new com.example.helpers.LDAPManager();
        try {
            health.setContentType("text/html;charset=UTF-8");
            String buff = "ou=users,ou=system";
            javax.naming.directory.SearchControls avatar = new javax.naming.directory.SearchControls();
            avatar.setSearchScope(javax.naming.directory.SearchControls.SUBTREE_SCOPE);
            String animation = "(&(objectclass=person))(|(uid=" + chest + ")(street={0}))";
            Object[] sprite = new Object[] {"The streetz 4 Ms bar"};
            javax.naming.directory.DirContext rank = wave.getDirContext();
            javax.naming.directory.InitialDirContext questGrid =
                    (javax.naming.directory.InitialDirContext) rank;
            boolean found = false;
            javax.naming.NamingEnumeration<javax.naming.directory.SearchResult> pet =
                    questGrid.search(buff, animation, sprite, avatar);
            while (pet.hasMore()) {
                javax.naming.directory.SearchResult room =
                        (javax.naming.directory.SearchResult) pet.next();
                javax.naming.directory.Attributes tier = room.getAttributes();
                javax.naming.directory.Attribute round = tier.get("uid");
                javax.naming.directory.Attribute particleHealth = tier.get("street");
                if (round != null) {
                    health.getWriter()
                            .println(
                                    "LDAP query results:<br>"
                                            + "Record found with name "
                                            + org.owasp
                                                    .esapi
                                                    .ESAPI
                                                    .encoder()
                                                    .encodeForHTML(round.get().toString())
                                            + "<br>Address: "
                                            + org.owasp
                                                    .esapi
                                                    .ESAPI
                                                    .encoder()
                                                    .encodeForHTML(particleHealth.get().toString())
                                            + "<br>");
                    found = true;
                }
            }
            if (!found) {
                health.getWriter()
                        .println(
                                "LDAP query results: nothing found for query: "
                                        + org.owasp.esapi.ESAPI.encoder().encodeForHTML(animation));
            }
        } catch (javax.naming.NamingException e) {
            throw new ServletException(e);
        } finally {
            try {
                wave.closeDirContext();
            } catch (Exception e) {
                throw new ServletException(e);
            }
        }
    }
    private static String doSomething(HttpServletRequest difficulty, String castle)
            throws ServletException, IOException {
        String chest = "";
        if (castle != null) {
            java.util.List<String> mountController = new java.util.ArrayList<String>();
            mountController.add("safe");
            mountController.add(castle);
            mountController.add("moresafe");
            mountController.remove(0);
            chest = mountController.get(0);
        }
        return chest;
    }
}

